/* @lc app=leetcode id=1254 lang=kotlin */ class Solution { fun set(g: Array<IntArray>, p: IntArray) { g[p[0]][p[1]] = 1 } fun fill(g: Array<IntArray>, i: Int, j: Int): List<IntArray> = java.util.ArrayDeque(listOf(intArrayOf(i, j))).also { set(g, intArrayOf(i, j)) }.let { q -> generateSequence { q.poll() }.onEach { p -> listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) }.filter { it[0] in g.indices && it[1] in g[0].indices && g[it[0]][it[1]] == 0 }.forEach { x -> set(g, x).also { q.add(x) } } }.toList() } fun closedIsland(grid: Array<IntArray>): Int = grid.indices.sumOf { i -> grid[0].indices.count { j -> grid[i][j] == 0 && fill(grid, i, j).none { it[0] == 0 || it[1] == 0 || it[0] == grid.size - 1 || it[1] == grid[0].size - 1 } } } }